css:
.cap-card__icon-button {
  position: absolute;
  top: 50%;
  right: 16px;
  z-index: 2;
  display: inline-grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border: 1px solid rgb(17 17 17 / 0.1);
  border-radius: 50%;
  background: #111111;
  color: #ffffff;
  transform: translateY(-50%);
}
